core=[tuple(map(int,w)) for w in zlib.decompress(base64.b85decode(CORE_DATA)).decode().split()]
assert len(core)==len(set(core))==308
assert all(len(w)==5 and all(0<=x<7 for x in w) for w in core)
W=list(product(range(7),repeat=5))
# Rebuild membership by direct pair tests, independently of LP incidence code.
U3={w for w in W if sum(all((x-y)%7 in (0,1,6) for x,y in zip(w,c)) for c in core)<=3}
assert len(U3)==4859
raw=zlib.decompress(base64.b85decode(DATA))
assert hashlib.sha256(raw).hexdigest()=='b1c544ce29736a3a72b2e032fca6e6a3456a7130553eb171def11ed888bd8fe6'
weights={};index=0
for gap,units in struct.iter_unpack('<HB',raw):
    index+=gap
    assert index<len(W) and W[index] in U3 and W[index] not in weights and 0<units<=64
    weights[W[index]]=units
# Each coordinate projection of a clique in C7 is contained in an edge.
# Consequently every strong-product clique is contained in one of these boxes.
maximum=0
for origin in W:
    load=sum(weights.get(w,0) for w in product(*[(x,(x+1)%7) for x in origin]))
    assert load<=64
    maximum=max(maximum,load)
assert len(weights)==2569 and sum(weights.values())==23696 and maximum==64
assert sum(weights.values())>368*64
print('U3=4859;2569 weighted vertices;max box load=64/64;total=23696/64=370.25.')
print('Every nonnegative clique cover of U3 has weight>=370.25; none has weight<368.')
print('This fractional witness is NOT an independent set of 368 or 370 vertices.')
